package app.noir.mobile;
import android.app.*;
import android.graphics.Color;
import android.widget.*;
import org.json.*;
import java.util.Calendar;

public final class ViewingEditor {
    static {String[][] words={{"Edit viewing","تعديل المشاهدة"},{"Approximate","تقريبي"},{"Unknown date","تاريخ غير معروف"},{"Delete this viewing?","حذف هذه المشاهدة؟"},{"Delete","حذف"},{"Save","حفظ"},{"Cancel","إلغاء"},{"Date","التاريخ"},{"Time","الوقت"}};for(String[] pair:words)Loc.AR.put(pair[0],pair[1]);}
    public static void open(Activity a,String itemId,String viewingId,Runnable onDone){DataStore data=NoirApp.data;JSONObject item=data.item(itemId);if(item==null)return;JSONObject viewing=null;for(JSONObject v:DataStore.objects(item.optJSONArray("viewings")))if(v.optString("id").equals(viewingId))viewing=v;if(viewing==null)return;
        Calendar when=Calendar.getInstance();long at=DataStore.date(viewing.optString("watchedAt"));if(at>0)when.setTimeInMillis(at);LinearLayout form=new LinearLayout(a);form.setOrientation(LinearLayout.VERTICAL);int pad=Math.round(20*a.getResources().getDisplayMetrics().density);form.setPadding(pad,pad/2,pad,pad/2);form.setBackgroundColor(Color.rgb(20,20,23));Button date=new Button(a),time=new Button(a);date.setAllCaps(false);time.setAllCaps(false);Runnable refresh=()->{date.setText(Loc.t("Date")+" · "+android.text.format.DateFormat.getDateFormat(a).format(when.getTime()));time.setText(Loc.t("Time")+" · "+android.text.format.DateFormat.getTimeFormat(a).format(when.getTime()));};refresh.run();form.addView(date);form.addView(time);CheckBox approximate=new CheckBox(a),unknown=new CheckBox(a);approximate.setText(Loc.t("Approximate"));unknown.setText(Loc.t("Unknown date"));approximate.setTextColor(Color.WHITE);unknown.setTextColor(Color.WHITE);approximate.setChecked(viewing.optBoolean("approximate"));unknown.setChecked(viewing.optBoolean("dateUnknown"));form.addView(approximate);form.addView(unknown);Runnable enabled=()->{date.setEnabled(!unknown.isChecked());time.setEnabled(!unknown.isChecked());approximate.setEnabled(!unknown.isChecked());};enabled.run();unknown.setOnCheckedChangeListener((v,checked)->enabled.run());date.setOnClickListener(v->{DatePickerDialog picker=new DatePickerDialog(a,(p,y,m,d)->{when.set(y,m,d);refresh.run();},when.get(Calendar.YEAR),when.get(Calendar.MONTH),when.get(Calendar.DAY_OF_MONTH));picker.getDatePicker().setMaxDate(System.currentTimeMillis());picker.show();});time.setOnClickListener(v->new TimePickerDialog(a,(p,h,m)->{when.set(Calendar.HOUR_OF_DAY,h);when.set(Calendar.MINUTE,m);refresh.run();},when.get(Calendar.HOUR_OF_DAY),when.get(Calendar.MINUTE),android.text.format.DateFormat.is24HourFormat(a)).show());
        new AlertDialog.Builder(a).setTitle(Loc.t("Edit viewing")).setView(form).setPositiveButton(Loc.t("Save"),(d,w)->{data.redateViewing(itemId,viewingId,unknown.isChecked()?0:when.getTimeInMillis(),approximate.isChecked());if(onDone!=null)onDone.run();}).setNegativeButton(Loc.t("Cancel"),null).setNeutralButton(Loc.t("Delete"),(d,w)->new AlertDialog.Builder(a).setMessage(Loc.t("Delete this viewing?")).setPositiveButton(Loc.t("Delete"),(x,y)->{data.deleteViewing(itemId,viewingId);if(onDone!=null)onDone.run();}).setNegativeButton(Loc.t("Cancel"),null).show()).show();
    }
}
